pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(address depositor, uint256 amount) public {
        amount = bound(amount, 1, 1 ether);
        if (depositor == address(0)) depositor = address(1);

        Receiver recv = new Receiver();

        vm.deal(depositor, amount);
        vm.prank(depositor);
        c.deposit{value: amount}();

        vm.deal(address(recv), amount);
        vm.prank(address(recv));
        c.deposit{value: amount}();

        bool ok;
        vm.prank(address(recv));
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

contract Receiver {
    receive() external payable {}
}
